    h, w = len(grid), len(grid[0])
    split_row = next((r for r, row in enumerate(grid) if len(set(row)) == 1 and r not in (0, h-1)), None)
    split_col = next((c for c in range(w) if len({grid[r][c] for r in range(h)}) == 1 and c not in (0, w-1)), None)
    if split_row is not None and (split_col is None or w >= h):
        region = grid[:split_row]
    elif split_col is not None:
        region = [row[:split_col] for row in grid]
    else:
        region = grid
    counts = {}
    for row in region:
        for value in row:
            counts[value] = counts.get(value, 0) + 1
